<script setup>
import { useForm, Link } from '@inertiajs/vue3'
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'
import WorkSubmissionDialogs from '@/Components/Manufacturing/WorkSubmissionDialogs.vue'
import { computed, ref } from 'vue'
import { Droplets, ClipboardList } from 'lucide-vue-next'

const props = defineProps({ fabrics: {type:Array,default:()=>[]}, materials: {type:Array,default:()=>[]}, assignedOrders: {type:Array,default:()=>[]} })
const selectedGroup=ref(null), selectedBatchId=ref(''), ids=ref([]), rows=ref([{inventory_item_id:'',quantity_used:''}])
const form=useForm({fabric_ids:[],materials_used:[]})
const confirmWork=ref(false), workSubmitting=ref(false), workResult=ref(null)
const batchId=f=>f.dyeing_batch_fabric?.dyeing_batch_id ?? f.dyeing_batch_fabric?.batch?.id
const joGroups=computed(()=>{const map=new Map();for(const fabric of props.fabrics){const key=fabric.sales_order_id??fabric.manufacturing_order_id;if(!map.has(key)){const jo=fabric.sales_order?.jo_number;const assigned=props.assignedOrders.find(o=>o.reference===jo);map.set(key,{key,reference:jo??`MO-${fabric.manufacturing_order_id}`,client:assigned?.client,recipe:assigned?.recipe,fabrics:[]})}map.get(key).fabrics.push(fabric)}return [...map.values()]})
const batchOptions=computed(()=>{const map=new Map();for(const f of selectedGroup.value?.fabrics??[]){const id=batchId(f);if(id&&!map.has(id))map.set(id,{id,machine:f.dyeing_batch_fabric?.batch?.machine?.machine_no,capacity:Number(f.dyeing_batch_fabric?.batch?.load_capacity_kg??0)})}return [...map.values()]})
const selectedMachine=computed(()=>batchOptions.value.find(b=>String(b.id)===String(selectedBatchId.value))?.machine)
const candidates=computed(()=>selectedGroup.value?.fabrics.filter(f=>!selectedMachine.value||f.dyeing_batch_fabric?.batch?.machine?.machine_no===selectedMachine.value)??[])
const selectedWeight=computed(()=>candidates.value.filter(f=>ids.value.includes(f.id)).reduce((n,f)=>n+Number(f.weight||0),0))
const capacity=computed(()=>batchOptions.value.filter(b=>b.machine===selectedMachine.value).reduce((n,b)=>n+b.capacity,0))
const open=g=>{selectedGroup.value=g;selectedBatchId.value=String((g.fabrics.find(f=>batchId(f))&&batchId(g.fabrics.find(f=>batchId(f))))??'');ids.value=[];rows.value=[{inventory_item_id:'',quantity_used:''}];form.clearErrors()}
const close=()=>{selectedGroup.value=null;ids.value=[];form.reset();form.clearErrors()}
const requestSubmit=()=>{workResult.value=null;confirmWork.value=true}
const submit=()=>{if(workSubmitting.value)return;workSubmitting.value=true;form.fabric_ids=ids.value;form.materials_used=rows.value.filter(r=>r.inventory_item_id&&Number(r.quantity_used)>0).map(r=>({inventory_item_id:Number(r.inventory_item_id),quantity_used:Number(r.quantity_used)}));form.post(route('man.staff.dyeing-bleaching.store-bleach'),{preserveScroll:true,onSuccess:(page)=>{const error=page.props.flash?.error;workResult.value=error?{success:false,title:'Could not record bleaching',message:error}:{success:true,title:'Bleaching recorded',message:page.props.flash?.message||'Bleaching work was recorded successfully.'};confirmWork.value=false;if(!error)close()},onError:(errors)=>{workResult.value={success:false,title:'Could not record bleaching',message:Object.values(errors||{}).flat().find(Boolean)||'The server could not save this work record. Review the form and try again.'};confirmWork.value=false},onHttpException:()=>{workResult.value={success:false,title:'Could not record bleaching',message:'The server returned an error while saving. Your work form is still open so you can try again.'};confirmWork.value=false},onFinish:()=>{workSubmitting.value=false}})}
function batchesFor(group){return new Set(group.fabrics.map(batchId).filter(Boolean)).size}
</script>

<template>
<AuthenticatedLayout title="Dyeing Bleaching Work"><div class="mx-auto max-w-7xl space-y-6 p-6">
<header class="flex flex-wrap items-center justify-between gap-4 rounded-3xl bg-gradient-to-br from-blue-700 to-violet-800 p-7 text-white"><div><p class="text-xs font-bold uppercase tracking-widest">Dyeing Department</p><h1 class="text-3xl font-black">Bleaching Work Queue</h1><p class="mt-1 text-sm">{{ fabrics.length }} fabric(s) waiting</p></div><Link :href="route('man.staff.dyeing-bleaching.history')" class="flex items-center gap-2 rounded-xl bg-white px-4 py-2 font-bold text-blue-800"><ClipboardList class="h-4 w-4"/> History</Link></header>
<section v-if="assignedOrders.some(order => order.deadline)" class="rounded-2xl border border-amber-200 bg-amber-50 p-4 dark:border-amber-900/50 dark:bg-amber-950/20"><h2 class="text-sm font-black text-amber-900 dark:text-amber-200">Assignment deadlines</h2><p v-for="order in assignedOrders.filter(item => item.deadline)" :key="order.assignment_id" class="mt-2 flex justify-between gap-3 text-xs text-amber-800 dark:text-amber-100"><span class="font-mono font-bold">{{ order.reference }}</span><span class="font-bold">{{ new Date(`${order.deadline}T00:00:00`).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) }}</span></p></section>
<p v-if="!joGroups.length" class="rounded-2xl border border-dashed p-12 text-center text-gray-500">{{ assignedOrders.length ? 'Your assigned Job Orders have no fabrics ready for bleaching yet.' : 'No Job Orders are assigned to you yet. The dyeing supervisor can assign the bleaching stage from JO Assignments.' }}</p>
<section v-else class="space-y-4"><article v-for="group in joGroups" :key="group.key" class="rounded-2xl border bg-white p-5 shadow-sm dark:border-zinc-800 dark:bg-zinc-900"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-mono text-lg font-black">{{ group.reference }}</h2><p v-if="group.client" class="text-sm text-slate-500">{{ group.client }}</p><p class="mt-1 text-xs text-slate-500">{{ group.fabrics.length }} fabric code(s) · {{ batchesFor(group) }} machine batch(es)</p></div><button @click="open(group)" class="rounded-xl bg-blue-700 px-4 py-2.5 text-sm font-bold text-white">Record bleaching for this JO</button></div>
<details v-if="group.recipe" class="mt-3 rounded-xl bg-slate-50 p-3 dark:bg-zinc-800"><summary class="cursor-pointer text-sm font-bold">Full approved recipe</summary><p class="mt-2 text-xs"><b>Product:</b> {{ group.recipe.product||'—' }} · <b>Yarn:</b> {{ group.recipe.yarn_type||'—' }} · <b>Color:</b> {{ group.recipe.dye_color||'—' }} · <b>Design:</b> {{ group.recipe.weave_design||'—' }}</p><div class="mt-2 grid gap-2 sm:grid-cols-2"><section v-for="section in group.recipe.material_groups||[]" :key="section.label" class="rounded-lg border bg-white p-2 text-xs dark:border-zinc-700 dark:bg-zinc-900"><p class="font-bold">{{ section.label }}</p><p v-if="!section.materials?.length" class="text-slate-500">None listed</p><p v-for="m in section.materials||[]" :key="m.material_id">{{ m.name }} · {{ m.quantity }} {{ m.unit||'' }}</p></section></div></details>
<div class="mt-3 flex flex-wrap gap-2"><span v-for="f in group.fabrics" :key="f.id" class="rounded-lg bg-blue-50 px-2.5 py-1.5 text-xs dark:bg-blue-500/10"><b class="font-mono">{{ f.code }}</b> · {{ f.weight }} kg · {{ f.dyeing_batch_fabric?.batch?.machine?.machine_no }}</span></div></article></section>
</div>
<div v-if="selectedGroup" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" @click.self="close"><form @submit.prevent="requestSubmit" class="max-h-[90vh] w-full max-w-2xl space-y-4 overflow-y-auto rounded-2xl bg-white p-5 shadow-xl dark:bg-zinc-900"><header><h2 class="text-xl font-black">Record bleaching · {{ selectedGroup.reference }}</h2><p class="text-sm text-slate-500">Choose one machine batch and select fabric codes within its load limit.</p></header>
<label v-if="batchOptions.length>1" class="block text-sm font-bold">Machine<select v-model="selectedBatchId" @change="ids=[]" required class="mt-1 w-full rounded-lg border p-3 dark:border-zinc-700 dark:bg-zinc-800"><option v-for="b in batchOptions" :key="b.id" :value="String(b.id)">{{ b.machine }}</option></select></label><p class="text-xs text-slate-500">Machine {{ selectedMachine }} · Selected {{ selectedWeight.toFixed(2) }} / {{ capacity }} kg across this machine's batches</p>
<section class="space-y-2"><label v-for="f in candidates" :key="f.id" class="flex justify-between rounded-lg border p-3 text-sm dark:border-zinc-700"><span class="flex gap-2"><input v-model="ids" type="checkbox" :value="f.id"><span class="font-mono font-bold">{{ f.code }}</span></span><span>{{ f.weight }} kg</span></label><p v-if="form.errors.fabric_ids" class="text-xs text-rose-600">{{ form.errors.fabric_ids }}</p></section>
<section><div class="mb-2 flex justify-between"><h3 class="font-bold">Pre-treatment materials used (kg)</h3><button type="button" @click="rows.push({inventory_item_id:'',quantity_used:''})" class="text-sm font-bold text-blue-700">+ Add material</button></div><div v-for="(row,i) in rows" :key="i" class="mb-2 grid grid-cols-[1fr_120px_auto] gap-2"><select v-model="row.inventory_item_id" required class="rounded-lg border p-2 text-sm dark:border-zinc-700 dark:bg-zinc-800"><option value="">Select pre-treatment material</option><option v-for="m in materials" :key="m.id" :value="m.id">{{ m.name }} · {{ m.control_number }} ({{ m.remaining_quantity }} kg)</option></select><input v-model="row.quantity_used" type="number" min="0.01" step="0.01" required placeholder="kg used" class="rounded-lg border p-2 dark:border-zinc-700 dark:bg-zinc-800"><button v-if="rows.length>1" type="button" @click="rows.splice(i,1)" class="text-rose-600">Remove</button></div><p v-if="form.errors.materials_used" class="text-xs text-rose-600">{{ form.errors.materials_used }}</p></section>
<footer class="flex gap-3 border-t pt-4 dark:border-zinc-800"><button type="button" @click="close" class="flex-1 rounded-lg border p-3 font-bold">Cancel</button><button :disabled="form.processing||!ids.length||(capacity>0&&selectedWeight>capacity)" class="flex-1 rounded-lg bg-blue-700 p-3 font-bold text-white disabled:opacity-50">Submit for supervisor review</button></footer></form></div>
<WorkSubmissionDialogs :show-confirm="confirmWork" confirm-title="Confirm bleaching" :confirm-message="`Record bleaching work for ${selectedGroup?.reference || 'this JO'}?`" :confirm-detail="`${ids.length} fabric code(s) selected.`" :submitting="workSubmitting" :result="workResult" @cancel="confirmWork=false" @confirm="submit" @close-result="workResult=null" />
</AuthenticatedLayout>
</template>
